{"name": "create_pacman_clone_html", "type": "sequential", "steps": [
  {"tool": "file_write",
   "args": {"path": "$profile.workspace/pacman.html", "content": "<!DOCTYPE html>
<html lang='en'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>Pac-Man Clone</title>
<style>
  body { margin: 0; background: black; }
  canvas { display: block; margin: 0 auto; background: black; }
</style>
</head>
<body>
<canvas id='game' width='560' height='620'></canvas>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const tileSize = 20;
let pacman = { x: 14, y: 23, dir: 'left', mouth: 0 };
let map = [];
for (let y = 0; y < 31; y++) {
  map[y] = [];
  for (let x = 0; x < 28; x++) {
    map[y][x] = (x === 0 || y === 0 || x === 27 || y === 30) ? 1 : 0;
  }
}
function drawMap() {
  for (let y = 0; y < map.length; y++) {
    for (let x = 0; x < map[y].length; x++) {
      if (map[y][x] === 1) {
        ctx.fillStyle = 'blue';
        ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
      } else {
        ctx.fillStyle = 'black';
        ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
        ctx.fillStyle = 'white';
        ctx.beginPath();
        ctx.arc(x * tileSize + tileSize/2, y * tileSize + tileSize/2, 2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
}
function drawPacman() {
  const angle = Math.PI / 4 * pacman.mouth;
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  let start = 0, end = 2 * Math.PI;
  if (pacman.dir === 'right') { start = angle; end = 2*Math.PI - angle; }
  if (pacman.dir === 'left') { start = Math.PI + angle; end = Math.PI - angle; }
  if (pacman.dir === 'up') { start = 1.5*Math.PI + angle; end = 1.5*Math.PI - angle; }
  if (pacman.dir === 'down') { start = 0.5*Math.PI + angle; end = 0.5*Math.PI - angle; }
  ctx.arc(pacman.x * tileSize + tileSize/2, pacman.y * tileSize + tileSize/2, tileSize/2, start, end);
  ctx.lineTo(pacman.x * tileSize + tileSize/2, pacman.y * tileSize + tileSize/2);
  ctx.fill();
}
function loop() {
  ctx.clearRect(0,0,canvas.width,canvas.height);
  drawMap();
  drawPacman();
  pacman.mouth = (pacman.mouth + 1) % 8;
  requestAnimationFrame(loop);
}
window.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') pacman.dir = 'left';
  if (e.key === 'ArrowRight') pacman.dir = 'right';
  if (e.key === 'ArrowUp') pacman.dir = 'up';
  if (e.key === 'ArrowDown') pacman.dir = 'down';
});
loop();
</script>
</body>
</html>"},
   "store_result_as": "$file",
   "description": "Create a simple HTML Pac-Man clone file in the user's workspace"},
  {"tool": "app_open",
   "args": {"target": "$profile.workspace/pacman.html"},
   "description": "Open the newly created Pac-Man clone in the system's default browser"}
]}

